const properties = $('API 1 - Properties API').first().json;
const residences = $('API 2 - Residences API').first().json;
const amenities = $('API 3 - Amenities API').first().json;

return [
  {
    json: {
      properties,
      residences,
      amenities
    }
  }
];

const items = $input.all();

// -----------------------------------
// 1. Get the 3 API responses
// -----------------------------------

const propertiesResponse = items[0].json;
const residencesResponse = items[1].json;
const amenitiesResponse = items[2].json;

// Extract data arrays
const properties = propertiesResponse.data || [];
const residences = residencesResponse.data || [];
const amenities = amenitiesResponse.data || [];


// -----------------------------------
// 2. Create lookup maps
// -----------------------------------

// Residence → property
const residencesByPropertyId = {};

for (const residence of residences) {
  const propertyId = residence.property?.id;

  if (!propertyId) continue;

  if (!residencesByPropertyId[propertyId]) {
    residencesByPropertyId[propertyId] = [];
  }

  residencesByPropertyId[propertyId].push(residence);
}


// Amenity → property
const amenitiesByPropertyId = {};

for (const amenity of amenities) {
  const propertyId = amenity.property?.id;

  if (!propertyId) continue;

  if (!amenitiesByPropertyId[propertyId]) {
    amenitiesByPropertyId[propertyId] = [];
  }

  amenitiesByPropertyId[propertyId].push(amenity);
}


// -----------------------------------
// 3. Build one combined object
//    for every property
// -----------------------------------

const result = [];

for (const property of properties) {

  const propertyId = property.id;

  const matchedResidences =
    residencesByPropertyId[propertyId] || [];

  const matchedAmenities =
    amenitiesByPropertyId[propertyId] || [];

  result.push({
    json: {
      property: property,

      residences: matchedResidences,

      amenities: matchedAmenities,

      matching: {
        propertyId: propertyId,
        residenceCount: matchedResidences.length,
        amenityCount: matchedAmenities.length
      }
    }
  });
}


// -----------------------------------
// 4. Return one n8n item per property
// -----------------------------------

return result;

const items = $input.all();

return items.map(item => {
  const property = item.json.property || {};
  const residences = item.json.residences || [];
  const amenities = item.json.amenities || [];

  const overview = property.overview || {};
  const propertyType = property.property_type || {};

  // -----------------------------------------
  // RERA
  // -----------------------------------------

  const reraNumbers = (property.rera_numbers || []).map(rera => ({
    tower_name: rera.wing || null,
    rera_number: rera.rera_number || null,
    rera_url: null,
    image_url: rera.image?.url || null
  }));


  // -----------------------------------------
  // RESIDENCE / PROJECT PLANS
  // -----------------------------------------

  const plans = [];

  for (const residence of residences) {

    for (const content of (residence.content || [])) {

      if (content.__component !== 'properties.project-plan') {
        continue;
      }

      for (const unitPlan of (content.unitPlan || [])) {

        for (const card of (unitPlan.unitPlanCard || [])) {

          const imageUrl = card.image?.url || null;
          const pdfUrl = card.pdf?.url || null;

          // Use image first, otherwise PDF
          const planUrl = imageUrl || pdfUrl;

          if (!planUrl) {
            continue;
          }

          // Build plan name
          // Example:
          // 2 BHK - Wing B - 650 sq. ft.
          const nameParts = [
            unitPlan.typeOfBhk,
            card.tower,
            card.area
          ].filter(Boolean);

          const planName = nameParts.join(' - ');

          plans.push({
            name: planName,

            images: [
              planUrl
            ],

            images_1_by_1: [
              planUrl
            ],

            images_16_by_9: [
              planUrl
            ]
          });
        }
      }
    }
  }


  // -----------------------------------------
  // FLOOR PLANS
  // -----------------------------------------

  const floorPlans = [];

  for (const residence of residences) {

    for (const content of (residence.content || [])) {

      if (content.__component !== 'properties.project-plan') {
        continue;
      }

      for (const floorPlan of (content.floorPlan || [])) {

        floorPlans.push({
          name: floorPlan.level || null,
          image: floorPlan.image?.url || null,
          pdf: floorPlan.pdf?.url || null
        });

      }
    }
  }


  // -----------------------------------------
  // PROJECT 2D / FLOOR PLAN IMAGES
  // -----------------------------------------

  const project2DImages = [];

  for (const floorPlan of floorPlans) {

    if (floorPlan.image) {
      project2DImages.push(floorPlan.image);
    }

    if (floorPlan.pdf) {
      project2DImages.push(floorPlan.pdf);
    }

  }


  // -----------------------------------------
  // MASTER PLANS
  // -----------------------------------------

  const masterPlans = [];

  for (const residence of residences) {

    for (const content of (residence.content || [])) {

      if (content.__component !== 'properties.project-plan') {
        continue;
      }

      if (content.masterPlan?.mapViewPdf?.url) {

        masterPlans.push({
          image: content.masterPlan.mapViewPdf.url
        });

      }
    }
  }


  // -----------------------------------------
  // AMENITIES
  // -----------------------------------------

  const amenityList = [];

  for (const amenity of amenities) {

    for (const content of (amenity.content || [])) {

      // ---------------------------------------
      // Other Amenities
      // ---------------------------------------

      if (content.__component === 'properties.other-amenties') {

        for (const amenityItem of (content.imageTitle || [])) {

          amenityList.push({
            name:
              amenityItem.description ||
              amenityItem.title ||
              null,

            image:
              amenityItem.image?.url ||
              null
          });

        }
      }


      // ---------------------------------------
      // About Properties
      // ---------------------------------------

      if (content.__component === 'home.about-properties') {

        amenityList.push({
          name: content.title || null,

          description:
            content.description ||
            null,

          image:
            content.desktopbanner?.url ||
            null,

          mobile_image:
            content.mobilebanner?.url ||
            null
        });

      }
    }
  }


  // -----------------------------------------
  // PROPERTY BANNER IMAGES
  // -----------------------------------------

  const bannerImages = [];

  for (const content of (property.content || [])) {

    if (content.desktopbanner?.url) {

      bannerImages.push({
        type: 'desktop',
        url: content.desktopbanner.url
      });

    }

    if (content.mobilebanner?.url) {

      bannerImages.push({
        type: 'mobile',
        url: content.mobilebanner.url
      });

    }
  }


  // -----------------------------------------
  // FINAL NORMALIZED OBJECT
  // -----------------------------------------

  return {
    json: {

      // ---------------------------------------
      // ORIGINAL SOURCE DATA
      // ---------------------------------------

      source: {
        property: property,
        residences: residences,
        amenities: amenities
      },


      // ---------------------------------------
      // NORMALIZED PROJECT DATA
      // ---------------------------------------

      project: {

        id:
          property.id ||
          null,

        documentId:
          property.documentId ||
          null,

        slug:
          property.slug ||
          null,

        name:
          property.title ||
          null,

        property_type:
          propertyType.name ||
          null,

        construction_status:
          overview.status ||
          null,

        configuration:
          overview.configuration ||
          overview.unit_type ||
          null,

        city:
          property.city ||
          null,

        latitude:
          property.latitude ||
          null,

        longitude:
          property.longitude ||
          null,

        location:
          overview.location ||
          null,


        // -------------------------------------
        // RERA
        // -------------------------------------

        rera_numbers:
          reraNumbers,


        // -------------------------------------
        // UNIT / PROJECT PLANS
        // -------------------------------------

        plans:
          plans,


        // -------------------------------------
        // FLOOR PLANS
        // -------------------------------------

        floor_plans:
          floorPlans,


        // -------------------------------------
        // LOCKATED PROJECT2DIMAGE
        // -------------------------------------

        Project2DImage:
