        // -------------------------------------
        // MASTER PLANS
        // -------------------------------------

        master_plans:
          masterPlans,


        // -------------------------------------
        // AMENITIES
        // -------------------------------------

        amenities:
          amenityList,


        // -------------------------------------
        // PROPERTY BANNER IMAGES
        // -------------------------------------

        banner_images:
          bannerImages
      }
    }
  };
});

