// ============================================================
// SHA-256 HELPERS
// ============================================================

function rightRotate(value, amount) {
  return (
    value >>> amount
  ) |
  (
    value << (32 - amount)
  );
}


function sha256(ascii) {

  const mathPow = Math.pow;
  const maxWord = mathPow(2, 32);

  let result = '';
  const words = [];

  const asciiBitLength =
    ascii.length * 8;

  let hash =
    sha256.h =
      sha256.h ||
      [];

  let k =
    sha256.k =
      sha256.k ||
      [];

  let primeCounter =
    k.length;

  const isComposite = {};

  while (primeCounter < 64) {

    let candidate =
      primeCounter + 2;

    while (isComposite[candidate]) {
      candidate++;
    }

    for (
      let i = 0;
      i < 313;
      i += candidate
    ) {
      isComposite[i] =
        candidate;
    }

    hash[primeCounter] =
      (
        mathPow(candidate, 0.5) *
        maxWord
      ) | 0;

    k[primeCounter] =
      (
        mathPow(candidate, 1 / 3) *
        maxWord
      ) | 0;

    primeCounter++;
  }

  ascii += '\x80';

  while (
    ascii.length % 64 - 56
  ) {
    ascii += '\x00';
  }

  for (
    let i = 0;
    i < ascii.length;
    i++
  ) {

    const j =
      ascii.charCodeAt(i);

    if (j > 255) {
      throw new Error(
        'SHA-256 input contains non-Latin1 characters.'
      );
    }

    words[i >> 2] |=
      j <<
      (
        8 *
        (
          3 -
          (i % 4)
        )
      );
  }

  words.push(
    Math.floor(
      asciiBitLength /
      maxWord
    )
  );

  words.push(
    asciiBitLength
  );

  for (
    let j = 0;
    j < words.length;
  ) {

    const w =
      words.slice(
        j,
        j += 16
      );

    const oldHash =
      hash.slice(0);

    hash =
      hash.slice(0);

    for (
      let i = 0;
      i < 64;
      i++
    ) {

      const w15 =
        w[i - 15];

      const w2 =
        w[i - 2];

      const a =
        hash[0];

      const e =
        hash[4];

      const temp1 =
        (
          hash[7] +
          (
            rightRotate(e, 6) ^
            rightRotate(e, 11) ^
            rightRotate(e, 25)
          ) +
          (
            (e & hash[5]) ^
            (~e & hash[6])
          ) +
          k[i] +
          (
            w[i] =
              i < 16
                ? w[i]
                : (
                    w[i - 16] +
                    (
                      rightRotate(w15, 7) ^
                      rightRotate(w15, 18) ^
                      (w15 >>> 3)
                    ) +
                    w[i - 7] +
                    (
                      rightRotate(w2, 17) ^
                      rightRotate(w2, 19) ^
                      (w2 >>> 10)
                    )
                  ) | 0
          )
        ) | 0;

      const temp2 =
        (
          (
            rightRotate(a, 2) ^
            rightRotate(a, 13) ^
            rightRotate(a, 22)
          ) +
          (
            (a & hash[1]) ^
            (a & hash[2]) ^
            (hash[1] & hash[2])
          )
        ) | 0;

      hash = [
        (temp1 + temp2) | 0,
        hash[0],
        hash[1],
        hash[2],
        (hash[3] + temp1) | 0,
        hash[4],
        hash[5],
        hash[6]
      ];
    }

    for (
      let i = 0;
      i < 8;
      i++
    ) {

      hash[i] =
        (
          hash[i] +
          oldHash[i]
        ) | 0;
    }
  }

  for (
    let i = 0;
    i < 8;
    i++
  ) {

    for (
      let j = 3;
      j + 1;
      j--
    ) {

      const b =
        (
          hash[i] >>
          (
            j * 8
          )
        ) &
        255;

      result +=
        (
          b < 16
            ? '0'
            : ''
        ) +
        b.toString(16);
    }
  }

  return result;
}


// ============================================================
// SORT OBJECT FOR STABLE HASH
// ============================================================

function sortObject(value) {

  if (Array.isArray(value)) {
    return value.map(sortObject);
  }

  if (
    value !== null &&
    typeof value === 'object'
  ) {

    return Object.keys(value)
      .sort()
      .reduce((result, key) => {

        result[key] =
          sortObject(value[key]);

        return result;

      }, {});
  }

  return value;
}


