  const bannerImages =
    transformedProject.banner_images || [];

  let mobileBanner = null;
  let desktopBanner = null;

  for (const banner of bannerImages) {

    if (
      banner.type === 'mobile' &&
      !mobileBanner
    ) {
      mobileBanner =
        banner.url;
    }

    if (
      banner.type === 'desktop' &&
      !desktopBanner
    ) {
      desktopBanner =
        banner.url;
    }
  }

