    Location:
      project.Location,

    Rera_Number_multiple:
      project.Rera_Number_multiple,

    amenities:
      project.amenities,

    plans:
      project.plans,

    project_2d_image_1_by_1:
      project.project_2d_image_1_by_1,

    cover_images_1_by_1:
      project.cover_images_1_by_1,

    cover_images_16_by_9:
      project.cover_images_16_by_9,

    cover_images_9_by_16:
      project.cover_images_9_by_16,

    cover_images_3_by_2:
      project.cover_images_3_by_2,

    image_1_by_1:
      project.image_1_by_1,

    image_16_by_9:
      project.image_16_by_9,

    image_9_by_16:
      project.image_9_by_16,

    image_3_by_2:
      project.image_3_by_2,

    brochure:
      project.brochure || null
  };


// ============================================================
// 10. STABLE JSON STRING
// ============================================================

  const stableSyncData =
    sortObject(syncData);

  const syncDataString =
    JSON.stringify(stableSyncData);


// ============================================================
// 11. SOURCE HASH
// ============================================================

  const sourceHash =
    sha256(syncDataString);


// ============================================================
// 12. FINAL OUTPUT
// ============================================================

  return {
    json: {

      project,

      sync_data:
        syncData,

      sync_data_string:
        syncDataString,

      source_hash:
        sourceHash
    }
  };

});

