const items = $input.all();

return items.map(item => {

  // ==================================================
  // SOURCE DATA
  // ==================================================

  const source = item.json.source || {};

  const property = source.property || {};

  const overview = property.overview || {};

  const propertyType = property.property_type || {};


  // ==================================================
  // PROPERTY BANNER / HERO IMAGES
  // ==================================================

  let mobileBanner = null;
  let desktopBanner = null;

  for (const content of (property.content || [])) {

    // Mobile banner
    if (!mobileBanner && content.mobilebanner?.url) {
      mobileBanner = content.mobilebanner.url;
    }

    // Desktop banner
    if (!desktopBanner && content.desktopbanner?.url) {
      desktopBanner = content.desktopbanner.url;
    }

  }


  // ==================================================
  // BROCHURE
  // ==================================================

  const brochureUrl =
    property.brochure?.media?.url || null;


  // ==================================================
  // RERA
  // ==================================================

  const reraNumbers = (property.rera_numbers || []).map(rera => ({

    tower_name:
      rera.wing || null,

    rera_number:
      rera.rera_number || null,

    // RERA image URL
    rera_url:
      rera.image?.url || null

  }));


  // Convert RERA array into indexed object

  const reraMultiple = Object.fromEntries(

    reraNumbers.map((rera, index) => [

      String(index),

      rera

    ])

  );


  // ==================================================
  // AMENITIES
  // ==================================================

  const amenitiesArray = [];


  // --------------------------------------------------
  // Loop through all amenity source records
  // --------------------------------------------------

  for (const amenity of (source.amenities || [])) {

    for (const content of (amenity.content || [])) {


      // ==============================================
      // HOME.ABOUT-PROPERTIES
      // ==============================================

      if (
        content.__component === 'home.about-properties'
      ) {

        if (
          content.title ||
          content.desktopbanner?.url
        ) {

          amenitiesArray.push({

            name:
              content.title || null,

            icon_url:
              content.desktopbanner?.url || null

          });

        }

      }


      // ==============================================
      // PROPERTIES.OTHER-AMENIES
      // ==============================================

      if (
        content.__component === 'properties.other-amenties'
      ) {

        for (
          const amenityItem of (content.imageTitle || [])
        ) {

          amenitiesArray.push({

