function sha256(str) {

  // Convert JavaScript UTF-16 string to UTF-8 bytes
  const utf8 = unescape(encodeURIComponent(str));

  function rightRotate(value, amount) {
    return (value >>> amount) | (value << (32 - amount));
  }

  const mathPow = Math.pow;
  const maxWord = mathPow(2, 32);

  let result = '';

  const words = [];

  const asciiBitLength = utf8.length * 8;

  let hash = [];
  const k = [];

  let primeCounter = 0;

  const isPrime = [];

  for (let candidate = 2; primeCounter < 64; candidate++) {

    if (!isPrime[candidate]) {

      for (
        let i = 0;
        i < 313;
        i += candidate
      ) {
        isPrime[i] = candidate;
      }

      hash[primeCounter] =
        (
          Math.pow(candidate, 1 / 2) *
          maxWord
        ) | 0;

      k[primeCounter++] =
        (
          Math.pow(candidate, 1 / 3) *
          maxWord
        ) | 0;
    }
  }

  // Add the UTF-8 bytes
  for (let i = 0; i < utf8.length; i++) {

    const charCode =
      utf8.charCodeAt(i);

    words[i >> 2] |=
      charCode <<
      ((3 - i) % 4 * 8);
  }

  // Padding
  words[utf8.length >> 2] |=
    0x80 <<
    ((3 - utf8.length) % 4 * 8);

  words[((utf8.length + 8) >> 6 << 4) + 15] =
    asciiBitLength;

  for (
    let j = 0;
    j < words.length;
  ) {

    const w = words.slice(
      j,
      j += 16
    );

    const oldHash =
      hash.slice(0);

    for (
      let i = 0;
      i < 64;
      i++
    ) {

      const w15 = w[i - 15];
      const w2 = w[i - 2];

      const a = hash[0];
      const e = hash[4];

      const temp1 =
        hash[7] +
        (
          rightRotate(e, 6) ^
          rightRotate(e, 11) ^
          rightRotate(e, 25)
        ) +
        (
          (e & hash[5]) ^
          (~e & hash[6])
        ) +
        k[i] +
        (
          w[i] =
            i < 16
              ? w[i] || 0
              : (
                  (
                    rightRotate(w15, 7) ^
                    rightRotate(w15, 18) ^
                    (w15 >>> 3)
                  ) +
                  w[i - 16] +
                  (
                    rightRotate(w2, 17) ^
                    rightRotate(w2, 19) ^
                    (w2 >>> 10)
                  )
                )
        );

      const temp2 =
        (
          rightRotate(a, 2) ^
          rightRotate(a, 13) ^
          rightRotate(a, 22)
        ) +
        (
          (a & hash[1]) ^
          (a & hash[2]) ^
          (hash[1] & hash[2])
        );

      hash = [
        (temp1 + temp2) | 0,
        hash[0],
        hash[1],
        hash[2],
        (hash[3] + temp1) | 0,
        hash[4],
        hash[5],
        hash[6]
      ];
    }

    for (
      let i = 0;
      i < 8;
      i++
    ) {

      hash[i] =
        (hash[i] + oldHash[i]) | 0;
    }
  }

  for (
    let i = 0;
    i < 8;
    i++
  ) {

    for (
      let j = 3;
      j >= 0;
      j--
    ) {

      const byte =
        (hash[i] >> (j * 8)) & 255;

      result +=
        ('0' + byte.toString(16))
        .slice(-2);
    }
  }

  return result;
}


